import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * java-01 示例：基本类型与包装类型、缓存、拆箱、String 与值传递
 *
 * 编译运行：
 *   javac -encoding UTF-8 TypeBoxingDemo.java
 *   java TypeBoxingDemo
 */
public class TypeBoxingDemo {

    /** 值对象：手写 equals/hashCode，演示哈希契约 */
    static final class OrderKey {
        private final long userId;
        private final String sku;

        OrderKey(long userId, String sku) {
            this.userId = userId;
            this.sku = Objects.requireNonNull(sku, "sku");
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof OrderKey other)) {
                return false;
            }
            return userId == other.userId && sku.equals(other.sku);
        }

        @Override
        public int hashCode() {
            return Objects.hash(userId, sku);
        }

        @Override
        public String toString() {
            return "OrderKey[" + userId + "," + sku + "]";
        }
    }

    public static void main(String[] args) {
        // 1. 缓存边界：-128..127 由 valueOf 缓存，127 是同一个对象，128 不是
        Integer a = 127;
        Integer b = 127;
        Integer c = 128;
        Integer d = 128;
        System.out.println("127 == 127 -> " + (a == b));          // true
        System.out.println("128 == 128 -> " + (c == d));          // false
        System.out.println("128 equals 128 -> " + c.equals(d));   // true

        // 2. 一边是基本类型时包装类型会拆箱，比较的是值
        Integer big = 1000;
        System.out.println("big == 1000 -> " + (big == 1000));    // true

        // 3. null 拆箱：编译器插入 intValue()
        Integer missing = null;
        try {
            int v = missing;
            System.out.println("v = " + v);
        } catch (NullPointerException e) {
            System.out.println("拆箱 null -> NPE");               // 本行输出
        }

        // 4. 三元表达式把 Integer 与 int 统一为 int，选中的 null 分支要拆箱
        Map<String, Integer> stock = new HashMap<>();
        stock.put("apple", 3);
        stock.put("pear", null);              // 键存在，值缺失
        boolean hasPear = stock.containsKey("pear");
        try {
            int n = hasPear ? stock.get("pear") : 0;
            System.out.println("n = " + n);
        } catch (NullPointerException e) {
            System.out.println("三元混用 -> NPE");                 // 本行输出
        }

        // 5. 字面量、new String 与 intern 的身份差异
        String s1 = "note";
        String s2 = "note";
        String s3 = new String("note");
        String s4 = s3.intern();
        System.out.println("s1 == s2 -> " + (s1 == s2));           // true
        System.out.println("s1 == s3 -> " + (s1 == s3));           // false
        System.out.println("s1 == s4 -> " + (s1 == s4));           // true

        // 6. 常量折叠：final 的编译期常量会让拼接在编译期完成
        final String prefix = "no";
        String folded = prefix + "te";
        System.out.println("folded == s1 -> " + (folded == s1));   // true

        String runtimePrefix = "no";
        String runtime = runtimePrefix + "te";
        System.out.println("runtime == s1 -> " + (runtime == s1)); // false

        // 7. 值传递：改内容可见，改指向不可见
        StringBuilder sb = new StringBuilder("A");
        append(sb);
        System.out.println("append 之后 -> " + sb);                 // AB
        reassign(sb);
        System.out.println("reassign 之后 -> " + sb);               // AB

        // 8. equals/hashCode 一致才能从 HashMap 取回
        Map<OrderKey, Integer> orders = new HashMap<>();
        orders.put(new OrderKey(7L, "SKU-1"), 1);
        System.out.println("map 命中 -> " + orders.get(new OrderKey(7L, "SKU-1"))); // 1

        // 9. Map<Long, ?> 用 Integer 去 get：编译通过，运行时 equals 为 false
        Map<Long, String> names = new HashMap<>();
        names.put(1L, "alice");
        System.out.println("get(1) -> " + names.get(1));            // null
        System.out.println("get(1L) -> " + names.get(1L));          // alice

        // 10. 二进制浮点与十进制金额
        System.out.println("0.1 + 0.2 = " + (0.1 + 0.2));           // 0.30000000000000004
        BigDecimal exact = new BigDecimal("0.1").add(new BigDecimal("0.2"));
        System.out.println("BigDecimal = " + exact);                // 0.3
        System.out.println("equals 比 scale -> "
                + new BigDecimal("1.0").equals(new BigDecimal("1.00")));      // false
        System.out.println("compareTo 比值 -> "
                + new BigDecimal("1.0").compareTo(new BigDecimal("1.00")));   // 0
    }

    /** 改对象内容：调用方可见 */
    static void append(StringBuilder builder) {
        builder.append("B");
    }

    /** 改引用本身：调用方不可见 */
    static void reassign(StringBuilder builder) {
        builder = new StringBuilder("C");
    }
}

