import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;

/**
 * java-02 示例：remove 重载、hashCode 契约、fail-fast、subList 视图、容量与 null
 *
 * 编译运行：
 *   javac -encoding UTF-8 CollectionTraps.java
 *   java CollectionTraps
 */
public class CollectionTraps {

    /** 故意不写 equals/hashCode：两个内容相同的对象互不相等 */
    static final class BadKey {
        private final String code;

        BadKey(String code) {
            this.code = code;
        }

        @Override
        public String toString() {
            return "BadKey[" + code + "]";
        }
    }

    /** 正确实现：equals/hashCode 使用同一组字段 */
    static final class GoodKey {
        private final String code;

        GoodKey(String code) {
            this.code = Objects.requireNonNull(code);
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof GoodKey other && code.equals(other.code);
        }

        @Override
        public int hashCode() {
            return code.hashCode();
        }

        @Override
        public String toString() {
            return "GoodKey[" + code + "]";
        }
    }

    public static void main(String[] args) {
        // 1. remove(int) 与 remove(Object)
        List<Integer> nums = new ArrayList<>(List.of(10, 20, 30));
        nums.remove(1);                                        // 删下标 1
        System.out.println("remove(1) -> " + nums);            // [10, 30]

        List<Integer> nums2 = new ArrayList<>(List.of(10, 20, 30));
        nums2.remove(Integer.valueOf(20));                     // 删值 20
        System.out.println("remove(Integer 20) -> " + nums2);  // [10, 30]

        // 2. key 没有 equals/hashCode：放得进，取不出
        Map<BadKey, String> bad = new HashMap<>();
        bad.put(new BadKey("A-1"), "created");
        System.out.println("bad.get -> " + bad.get(new BadKey("A-1"))); // null
        System.out.println("bad.size -> " + bad.size());                // 1

        Map<GoodKey, String> good = new HashMap<>();
        good.put(new GoodKey("A-1"), "created");
        System.out.println("good.get -> " + good.get(new GoodKey("A-1"))); // created

        // 3. for-each 中删除：fail-fast
        List<String> names = new ArrayList<>(List.of("a", "b", "c"));
        try {
            for (String name : names) {
                if (name.equals("a")) {
                    names.remove(name);       // 改 modCount
                }
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("for-each remove -> CME");      // 本行输出
        }
        System.out.println("CME 之后 -> " + names);             // [b, c]

        // 4. 正确做法：Iterator.remove 或 removeIf
        Iterator<String> it = names.iterator();
        while (it.hasNext()) {
            if (it.next().equals("b")) {
                it.remove();
            }
        }
        System.out.println("iterator.remove -> " + names);      // [c]
        names.removeIf(name -> name.equals("c"));
        System.out.println("removeIf -> " + names);             // []

        // 5. subList 是视图，不是拷贝
        List<Integer> all = new ArrayList<>(List.of(1, 2, 3, 4, 5));
        List<Integer> view = all.subList(1, 4);
        view.set(0, 99);
        System.out.println("view.set -> " + all);               // [1, 99, 3, 4, 5]
        List<Integer> copy = new ArrayList<>(view);
        copy.clear();
        System.out.println("copy.clear -> " + all);             // [1, 99, 3, 4, 5]

        // 6. 按 0.75 的负载因子预留容量
        int expected = 1000;
        int capacity = (int) Math.ceil(expected / 0.75);
        Map<String, Integer> sized = new HashMap<>(capacity);
        System.out.println("capacity hint -> " + capacity);     // 1334
        sized.put("k", 1);
        System.out.println("sized.size -> " + sized.size());    // 1

        // 7. 不可变工厂拒绝 null
        try {
            List.of("x", null);
        } catch (NullPointerException e) {
            System.out.println("List.of(null) -> NPE");         // 本行输出
        }

        // 8. ConcurrentHashMap 拒绝 null 值
        Map<String, String> concurrent = new ConcurrentHashMap<>();
        try {
            concurrent.put("k", null);
        } catch (NullPointerException e) {
            System.out.println("CHM.put(null) -> NPE");         // 本行输出
        }
    }
}

