import java.lang.reflect.Array;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class Adv04 {

    // 上界决定擦除结果，也决定 compareTo 能不能调
    static class Box<T extends Comparable<T>> {
        private final T value;

        Box(T value) {
            this.value = value;
        }

        T get() {
            return value;
        }

        int compareWith(Box<T> other) {
            return value.compareTo(other.value);
        }
    }

    // 接口方法擦除为 Object read()，实现返回 String，编译器补桥接
    interface Reader<T> {
        T read();
    }

    static class StringReader implements Reader<String> {
        @Override
        public String read() {
            return "ok";
        }
    }

    // PECS：src 只读、dst 只写
    static <T> void copy(List<? extends T> src, List<? super T> dst) {
        for (T item : src) {
            dst.add(item);
        }
    }

    // Class<T> token：运行时拿到真实类型才能造数组
    @SuppressWarnings("unchecked")
    static <T> T[] toArray(List<T> src, Class<T> type) {
        T[] arr = (T[]) Array.newInstance(type, src.size());
        return src.toArray(arr);
    }

    public static void main(String[] args) {
        Box<String> a = new Box<>("apple");
        Box<String> b = new Box<>("banana");
        System.out.println(a.compareWith(b));          // -1

        List<String> strings = new ArrayList<>();
        List<Integer> ints = new ArrayList<>();
        System.out.println(strings.getClass() == ints.getClass());   // true

        List<String> src = new ArrayList<>(List.of("x", "y"));
        List<Object> dst = new ArrayList<>();
        copy(src, dst);
        System.out.println(dst);                       // [x, y]

        int bridges = 0;
        for (Method m : StringReader.class.getDeclaredMethods()) {
            if (m.isBridge()) {
                bridges++;
                System.out.println(m.getName() + " -> " + m.getReturnType().getSimpleName());
            }
        }
        System.out.println("bridge count = " + bridges);   // bridge count = 1

        String[] arr = toArray(src, String.class);
        System.out.println(arr.length + " " + arr[0]);     // 2 x

        List raw = strings;
        raw.add(Integer.valueOf(42));
        try {
            String last = strings.get(strings.size() - 1);
            System.out.println(last);
        } catch (ClassCastException e) {
            System.out.println("CCE: " + e.getMessage());
        }
    }
}

