import java.io.BufferedReader;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.stream.Stream;

public class Adv06 {

    public static void main(String[] args) throws IOException {
        Path dir = Files.createTempDirectory("adv06-");
        Path csv = dir.resolve("orders.csv");
        Files.write(csv, List.of("id,amount", "u1,30", "u2,12"), StandardCharsets.UTF_8);

        // 字符层：显式编码 + try-with-resources + 逐行读
        long total = 0;
        int rows = 0;
        try (BufferedReader reader = Files.newBufferedReader(csv, StandardCharsets.UTF_8)) {
            reader.readLine();
            String line;
            while ((line = reader.readLine()) != null) {
                total += Long.parseLong(line.split(",")[1].trim());
                rows++;
            }
        }
        System.out.println("rows=" + rows + " total=" + total);      // rows=2 total=42

        // 字节层：Buffer 的 position / limit 怎么变
        try (FileChannel channel = FileChannel.open(csv, StandardOpenOption.READ)) {
            ByteBuffer buf = ByteBuffer.allocate(9);
            int n = channel.read(buf);
            System.out.println("read=" + n + " pos=" + buf.position() + " limit=" + buf.limit());
            buf.flip();
            byte[] head = new byte[buf.remaining()];
            buf.get(head);
            System.out.println("head=" + new String(head, StandardCharsets.US_ASCII));
        }

        // 零拷贝：内核直接把页缓存送到目标通道
        Path copy = dir.resolve("orders.copy.csv");
        try (FileChannel src = FileChannel.open(csv, StandardOpenOption.READ);
             FileChannel dst = FileChannel.open(copy, StandardOpenOption.CREATE,
                     StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE)) {
            long moved = src.transferTo(0, src.size(), dst);
            System.out.println("copiedAll=" + (moved == Files.size(csv)));   // copiedAll=true
        }

        // 原子写：临时文件 + 同目录原子改名
        Path tmp = dir.resolve("report.tmp");
        Path report = dir.resolve("report.txt");
        Files.writeString(tmp, "rows=" + rows + ",total=" + total, StandardCharsets.UTF_8);
        Files.move(tmp, report, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        System.out.println("report=" + Files.readString(report, StandardCharsets.UTF_8));  // rows=2,total=42

        // 目录遍历返回 Stream，必须关闭
        try (Stream<Path> paths = Files.list(dir)) {
            System.out.println("files=" + paths.count());                // files=3
        }

        Files.deleteIfExists(copy);
        Files.deleteIfExists(report);
        Files.deleteIfExists(csv);
        Files.deleteIfExists(dir);
        System.out.println("cleaned=" + !Files.exists(dir));             // cleaned=true
    }
}

