// Spring Boot 3.2 / Java 17，单文件版：存成 src/main/java/demo/OrderApplication.java
// pom 依赖：spring-boot-starter-web、spring-boot-starter-validation
// 运行：mvn spring-boot:run
// 验证（三条命令逐条执行，看首行状态码与 body）：
//   curl -i -X POST localhost:8080/api/orders -H "Content-Type: application/json" -d '{"sku":"A-1","quantity":2}'
//     → HTTP/1.1 201，Location: http://localhost:8080/api/orders/ORD-1
//   curl -i -X POST localhost:8080/api/orders -H "Content-Type: application/json" -d '{"sku":"","quantity":0}'
//     → HTTP/1.1 400，{"code":"VALIDATION_FAILED","fields":{"sku":"sku 不能为空","quantity":"数量必须大于 0"}}
//   curl -i -X PATCH localhost:8080/api/orders/ORD-1/status -H "Content-Type: application/json" -d '{"status":"SHIPPED"}'
//     → HTTP/1.1 409，{"code":"ILLEGAL_TRANSITION","message":"cannot move CREATED to SHIPPED"}
package demo;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import java.net.URI;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;

@SpringBootApplication
public class OrderApplication {

    public static void main(String[] args) {
        SpringApplication.run(OrderApplication.class, args);
    }

    // ---------- DTO：注解只是声明，只有参数上标了 @Valid 才会真的执行 ----------
    public record CreateOrderRequest(
            @NotBlank(message = "sku 不能为空") String sku,
            @Positive(message = "数量必须大于 0") int quantity) {
    }

    public record ChangeStatusRequest(@NotBlank(message = "status 不能为空") String status) {
    }

    public record Order(String id, String sku, int quantity, String status) {
    }

    // ---------- 领域异常：类型即语义，由 advice 翻译成状态码 ----------
    static class OrderNotFoundException extends RuntimeException {
        OrderNotFoundException(String id) {
            super("order not found: " + id);
        }
    }

    // ---------- Service：业务规则与状态机 ----------
    @Service
    static class OrderService {
        private final Map<String, Order> store = new ConcurrentHashMap<>();
        private final AtomicInteger seq = new AtomicInteger();

        Order create(CreateOrderRequest req) {
            String id = "ORD-" + seq.incrementAndGet();
            Order order = new Order(id, req.sku(), req.quantity(), "CREATED");
            store.put(id, order);
            return order;
        }

        Order get(String id) {
            Order order = store.get(id);
            if (order == null) {
                throw new OrderNotFoundException(id);
            }
            return order;
        }

        Order changeStatus(String id, String target) {
            // compute 对同一个 key 串行执行：先 get 再 put 会丢更新（两次 PAID）
            return store.compute(id, (key, current) -> {
                if (current == null) {
                    throw new OrderNotFoundException(key);
                }
                String next = switch (target) {
                    case "PAID" -> "CREATED".equals(current.status()) ? "PAID" : null;
                    case "SHIPPED" -> "PAID".equals(current.status()) ? "SHIPPED" : null;
                    default -> null;
                };
                if (next == null) {
                    throw new IllegalStateException("cannot move " + current.status() + " to " + target);
                }
                return new Order(current.id(), current.sku(), current.quantity(), next);
            });
        }
    }

    // ---------- Controller：只做协议转换，不写业务规则 ----------
    @RestController
    @RequestMapping("/api/orders")
    static class OrderController {
        private final OrderService service;

        OrderController(OrderService service) { // 构造器注入：显式、可测、可 final
            this.service = service;
        }

        @PostMapping
        ResponseEntity<Order> create(@Valid @RequestBody CreateOrderRequest req) {
            Order order = service.create(req);
            URI location = ServletUriComponentsBuilder.fromCurrentRequest()
                    .path("/{id}")
                    .buildAndExpand(order.id())
                    .toUri();
            return ResponseEntity.created(location).body(order);
        }

        @GetMapping("/{id}")
        Order get(@PathVariable String id) {
            return service.get(id);
        }

        @PatchMapping("/{id}/status")
        Order changeStatus(@PathVariable String id, @Valid @RequestBody ChangeStatusRequest req) {
            return service.changeStatus(id, req.status());
        }
    }

    // ---------- 统一异常处理：异常类型到 HTTP 状态码的唯一映射点 ----------
    @RestControllerAdvice
    static class ApiExceptionHandler {

        @ExceptionHandler(MethodArgumentNotValidException.class)
        ResponseEntity<Map<String, Object>> onInvalid(MethodArgumentNotValidException e) {
            Map<String, String> fields = new LinkedHashMap<>();
            for (FieldError error : e.getBindingResult().getFieldErrors()) {
                fields.putIfAbsent(error.getField(), error.getDefaultMessage());
            }
            return ResponseEntity.badRequest()
                    .body(Map.<String, Object>of("code", "VALIDATION_FAILED", "fields", fields));
        }

        @ExceptionHandler(OrderNotFoundException.class)
        ResponseEntity<Map<String, Object>> onMissing(OrderNotFoundException e) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Map.<String, Object>of("code", "ORDER_NOT_FOUND", "message", e.getMessage()));
        }

        @ExceptionHandler(IllegalStateException.class)
        ResponseEntity<Map<String, Object>> onConflict(IllegalStateException e) {
            return ResponseEntity.status(HttpStatus.CONFLICT)
                    .body(Map.<String, Object>of("code", "ILLEGAL_TRANSITION", "message", e.getMessage()));
        }
    }
}

