// 运行：java -Xmx64m -Xlog:gc MemoryDemo.java
// JDK 11+ 支持单文件源码启动，不需要先 javac；-Xlog:gc 会打印每次 Young/Full GC
// 预期（具体数字随 JDK 小版本浮动）：
//   max=64MB total=64MB
//   round=0 used=1MB ...
//   OOM: Java heap space
//   cache size before clear = 5x
//   round=-1 used=2MB          ← clear + System.gc() 之后明显回落
//   StackOverflowError
//   G1 Young Generation count=.. time=..ms
//   direct capacity = 8388608
import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

public class MemoryDemo {

    // 静态字段是 GC Root 可达的：放进去的数组永远死不掉，这就是泄漏的最小模型
    static final List<byte[]> CACHE = new ArrayList<>();

    public static void main(String[] args) {
        Runtime rt = Runtime.getRuntime();
        // maxMemory 是 -Xmx；totalMemory 是已向 OS 申请的堆；free 是 total 里的空闲
        System.out.printf("max=%dMB total=%dMB%n", rt.maxMemory() >> 20, rt.totalMemory() >> 20);

        // 直接内存：不受 -Xmx 限制，靠 Cleaner 回收
        ByteBuffer direct = ByteBuffer.allocateDirect(8 << 20);

        try {
            for (int i = 0; i < 10_000; i++) {
                CACHE.add(new byte[1 << 20]); // 每次 1MB，强引用持有
                if (i % 8 == 0) {
                    printUsage(rt, i);
                }
            }
        } catch (OutOfMemoryError e) { // OOM 是 Error，catch (Exception) 抓不到
            System.out.println("OOM: " + e.getMessage());
            System.out.println("cache size before clear = " + CACHE.size());
            CACHE.clear(); // 必须先断开引用，否则下一次分配继续失败
        }

        System.gc(); // 只是建议；G1 下通常是 Full GC，生产常被 -XX:+DisableExplicitGC 关掉
        printUsage(rt, -1);

        // 栈溢出与堆无关：每个线程的栈由 -Xss 决定
        try {
            deep(0);
        } catch (StackOverflowError e) {
            System.out.println("StackOverflowError");
        }

        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            System.out.printf("%s count=%d time=%dms%n",
                    gc.getName(), gc.getCollectionCount(), gc.getCollectionTime());
        }

        System.out.println("direct capacity = " + direct.capacity());

        // 观察类直方图（另开终端）：jcmd <pid> GC.class_histogram | head
        System.out.println("pid = " + ProcessHandle.current().pid());
    }

    static void printUsage(Runtime rt, int round) {
        long used = (rt.totalMemory() - rt.freeMemory()) >> 20;
        System.out.printf("round=%d used=%dMB%n", round, used);
    }

    static void deep(int n) {
        deep(n + 1);
    }
}

