// 运行：mvn -q test（依赖 spring-boot-starter-test：JUnit 5.10 + Mockito 5 + AssertJ）
// 单文件版：被测代码内嵌在下方，真实工程里放 src/main/java，测试放 src/test/java。
// 预期：Tests run: 6, Failures: 0, Errors: 0, Skipped: 0（两个普通用例 + 四组参数）
//       把 OrderService 的 <= 0 改成 < 0 之后，amount=0 那一组会变红（Failures: 1）。
package demo;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class) // 开启 Mockito 与 JUnit 5 的集成，负责创建 @Mock
@DisplayName("OrderService 单元测试")
class OrderServiceTest {

    @Mock
    private OrderRepository repo;

    // 时间也是依赖：固定住才能在断言里比较 createdAt
    private final Clock clock = Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"), ZoneOffset.UTC);

    private OrderService service;

    @BeforeEach
    void setUp() {
        // 手工构造而不是 @InjectMocks：构造器有两个参数时 @InjectMocks 会静默传 null
        service = new OrderService(repo, clock);
    }

    @Test
    @DisplayName("创建订单：状态 CREATED，时间来自注入的 Clock")
    void createsOrderWithFixedClock() {
        when(repo.findByNo("A-1")).thenReturn(Optional.empty());

        Order created = service.create(new CreateOrder("A-1", 1999));

        ArgumentCaptor<Order> captor = ArgumentCaptor.forClass(Order.class);
        verify(repo).save(captor.capture());
        assertThat(captor.getValue().status()).isEqualTo("CREATED");
        assertThat(captor.getValue().createdAt()).isEqualTo(Instant.parse("2026-01-01T00:00:00Z"));
        assertThat(created.orderNo()).isEqualTo("A-1");
    }

    @Test
    @DisplayName("重复单号：抛异常且不写库")
    void rejectsDuplicateOrderNo() {
        when(repo.findByNo("A-1"))
                .thenReturn(Optional.of(new Order("A-1", 1, "CREATED", Instant.EPOCH)));

        assertThatThrownBy(() -> service.create(new CreateOrder("A-1", 1999)))
                .isInstanceOf(DuplicateOrderException.class)
                .hasMessageContaining("A-1");
        verify(repo, never()).save(any());
    }

    @ParameterizedTest(name = "amount={0} 期望通过={1}")
    @CsvSource({"1,true", "1999,true", "0,false", "-5,false"})
    @DisplayName("金额边界：0 与负数在查库之前就被拒绝")
    void validatesAmount(long amount, boolean ok) {
        String orderNo = "A-" + amount;
        if (ok) {
            when(repo.findByNo(orderNo)).thenReturn(Optional.empty());
            assertThatCode(() -> service.create(new CreateOrder(orderNo, amount)))
                    .doesNotThrowAnyException();
        } else {
            assertThatThrownBy(() -> service.create(new CreateOrder(orderNo, amount)))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessage("amount must be positive");
            verify(repo, never()).findByNo(anyString());
            verify(repo, never()).save(any());
        }
    }

    // ---------- 以下是被测代码，真实工程放在 src/main/java ----------
    record CreateOrder(String orderNo, long amountCents) {
    }

    record Order(String orderNo, long amountCents, String status, Instant createdAt) {
    }

    static class DuplicateOrderException extends RuntimeException {
        DuplicateOrderException(String orderNo) {
            super("duplicate order: " + orderNo);
        }
    }

    interface OrderRepository {
        Optional<Order> findByNo(String orderNo);

        void save(Order order);
    }

    static class OrderService {
        private final OrderRepository repo;
        private final Clock clock;

        OrderService(OrderRepository repo, Clock clock) {
            this.repo = repo;
            this.clock = clock;
        }

        Order create(CreateOrder cmd) {
            if (cmd.amountCents() <= 0) { // 边界：0 也算非法
                throw new IllegalArgumentException("amount must be positive");
            }
            if (repo.findByNo(cmd.orderNo()).isPresent()) {
                throw new DuplicateOrderException(cmd.orderNo());
            }
            Order order = new Order(cmd.orderNo(), cmd.amountCents(), "CREATED", clock.instant());
            repo.save(order);
            return order;
        }
    }
}

