// GcLab.java —— Java 17，单文件可编译
//
// 编译：
//   javac -d out GcLab.java
//
// 运行（64MB 小堆 + 完整 GC 日志，日志落到当前目录 gc.log）：
//   java -Xms64m -Xmx64m -Xlog:gc*:file=gc.log:time,uptime,level,tags -cp out GcLab
//
// 运行（256MB 对照实验）：
//   java -Xms256m -Xmx256m -Xlog:gc*:file=gc256.log:time,uptime -cp out GcLab
//
// 复现内存溢出并自动 dump（第一个参数 0 = 缓存不设上界）：
//   java -Xmx48m -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=heap.hprof -cp out GcLab 0 20
//
// 运行期间另开终端诊断：
//   jcmd <pid> VM.flags
//   jcmd <pid> GC.heap_info
//   jcmd <pid> GC.class_histogram
//   jstat -gcutil <pid> 1000 5
//   jcmd <pid> GC.heap_dump /tmp/heap.hprof
//
// 预期输出（片段，pid 与数值每次都不同）：
//   pid=12345
//   maxHeapMB=64
//   pool=G1 Eden Space           used=2MB
//   pool=G1 Old Gen              used=0MB
//   pool=Metaspace               used=5MB
//   -- attach window starts, try: jcmd <pid> GC.heap_info --
//   created=...
//   gc=G1 Young Generation       count=... timeMs=...
//   gc=G1 Old Generation         count=0  timeMs=0

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.lang.management.MemoryPoolMXBean;
import java.util.ArrayList;
import java.util.List;

public class GcLab {

    // 订单快照：字段少、不可变，方便估算单个实例的字节数
    record Order(long id, String sku, int qty) { }

    public static void main(String[] args) throws Exception {
        // 第一个参数：缓存上界，0 表示不设上界（用来复现 OOM）
        int cacheLimit = args.length > 0 ? Integer.parseInt(args[0]) : 50_000;
        // 第二个参数：分配循环持续秒数，留出时间给另一个终端附着
        int seconds = args.length > 1 ? Integer.parseInt(args[1]) : 8;

        System.out.println("pid=" + ProcessHandle.current().pid());
        // maxMemory 是 JVM 认为可用的堆上限，受 -Xmx 与容器 limit 共同约束
        System.out.println("maxHeapMB=" + Runtime.getRuntime().maxMemory() / 1024 / 1024);
        System.out.println("cacheLimit=" + (cacheLimit == 0 ? "unbounded" : cacheLimit) + ", seconds=" + seconds);

        // 把 Eden / Old / Metaspace 分开打印，才能区分“堆满”与“元空间满”
        for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
            long usedMb = pool.getUsage() == null ? -1 : pool.getUsage().getUsed() / 1024 / 1024;
            System.out.printf("pool=%-26s used=%dMB%n", pool.getName(), usedMb);
        }
        System.out.println("-- attach window starts, try: jcmd <pid> GC.heap_info --");

        List<Order> cache = new ArrayList<>();
        long deadline = System.nanoTime() + seconds * 1_000_000_000L;
        long created = 0;
        while (System.nanoTime() < deadline) {
            // 每次循环丢弃两个新对象：分配速率就是这里制造出来的
            Order order = new Order(created++, "SKU-" + (created % 100), 1);
            // 千分之一被强引用 => 活过几轮 Young GC 后晋升老年代
            if ((created & 1023) == 0) {
                cache.add(order);
                // 有界缓存：设为 0 时这行不生效，程序就变成慢性泄漏
                if (cacheLimit > 0 && cache.size() > cacheLimit) {
                    cache.clear();
                }
            }
        }

        System.out.println("created=" + created + ", cache=" + cache.size());
        // GC 次数与累计耗时：和 gc.log 对照，确认自己看的是同一段时间
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            System.out.printf("gc=%-24s count=%d timeMs=%d%n",
                    gc.getName(), gc.getCollectionCount(), gc.getCollectionTime());
        }
    }
}

