// ConcurrencyLab.java —— Java 17，单文件可编译
//
// 编译：
//   javac -d out ConcurrencyLab.java
//
// 运行：
//   java -cp out ConcurrencyLab
//
// 附着观察（程序运行期间另开终端）：
//   jcmd <pid> Thread.print
//   jcmd <pid> GC.class_histogram
//
// 预期输出：
//   hits.A=4000
//   consumed=35000, maxBacklog=<0..16 之间，随调度变化>
//   recovered=downstream timeout
//   total=350
//   leaked=user-42;
//   afterRemove=[]

import java.util.Map;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class ConcurrencyLab {

    record Order(String id, int amount) { }

    // 毒丸：消费者读到它就退出，比 interrupt 更温和
    static final Order POISON = new Order("POISON", -1);
    // 每个线程一份追踪缓冲；不 remove 就会跟着线程池线程一直活着
    static final ThreadLocal<StringBuilder> TRACE = ThreadLocal.withInitial(StringBuilder::new);
    static final Map<String, Integer> PRICE = Map.of("A", 100, "B", 250);

    public static void main(String[] args) throws Exception {
        // 1) 复合操作：containsKey + put 会竞态，computeIfAbsent 一次完成
        ConcurrentHashMap<String, LongAdder> hits = new ConcurrentHashMap<>();
        ExecutorService workers = Executors.newFixedThreadPool(4);
        for (int t = 0; t < 4; t++) {
            workers.execute(() -> {
                for (int i = 0; i < 1000; i++) {
                    hits.computeIfAbsent("A", k -> new LongAdder()).increment();
                }
            });
        }
        workers.shutdown();
        workers.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("hits.A=" + hits.get("A").sum());

        // 2) 有界队列 + 毒丸：队列满时 put 阻塞，背压自然形成
        BlockingQueue<Order> queue = new ArrayBlockingQueue<>(16);
        AtomicLong consumedAmount = new AtomicLong();
        AtomicInteger maxBacklog = new AtomicInteger();

        Runnable consumer = () -> {
            try {
                while (true) {
                    Order o = queue.take();
                    if (o == POISON) {
                        return;
                    }
                    consumedAmount.addAndGet(o.amount());
                    // 记录队列曾经积压到多深，用来看背压是否生效
                    maxBacklog.accumulateAndGet(queue.size(), Math::max);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                TRACE.remove();
            }
        };
        Runnable producer = () -> {
            try {
                for (int i = 0; i < 100; i++) {
                    String sku = i % 2 == 0 ? "A" : "B";
                    queue.put(new Order(sku + "-" + i, PRICE.get(sku)));
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Thread c1 = new Thread(consumer, "consumer-1");
        Thread c2 = new Thread(consumer, "consumer-2");
        Thread p1 = new Thread(producer, "producer-1");
        Thread p2 = new Thread(producer, "producer-2");
        c1.start();
        c2.start();
        p1.start();
        p2.start();
        p1.join();
        p2.join();
        queue.put(POISON);   // 两个消费者，两粒毒丸
        queue.put(POISON);
        c1.join();
        c2.join();
        System.out.println("consumed=" + consumedAmount.get() + ", maxBacklog=" + maxBacklog.get());

        // 3) 组合：显式线程池 + exceptionally 兜底，一个失败不拖垮整条链
        ExecutorService io = Executors.newFixedThreadPool(4, r -> {
            Thread t = new Thread(r, "io-worker");
            t.setDaemon(true);   // 忘记 shutdown 也不会挂住 JVM
            return t;
        });
        CompletableFuture<Integer> fa = CompletableFuture.supplyAsync(() -> quote("A"), io);
        CompletableFuture<Integer> fb = CompletableFuture.supplyAsync(() -> quote("B"), io);
        CompletableFuture<Integer> fc = CompletableFuture.<Integer>supplyAsync(() -> {
            throw new IllegalStateException("downstream timeout");
        }, io).exceptionally(ex -> {
            System.out.println("recovered=" + ex.getCause().getMessage());
            return 0;
        });
        int total = fa.thenCombine(fb, Integer::sum).thenCombine(fc, Integer::sum).join();
        System.out.println("total=" + total);

        // 4) ThreadLocal：单线程池模拟 Web 容器复用线程
        ExecutorService single = Executors.newSingleThreadExecutor();
        single.submit(() -> TRACE.get().append("user-42;")).get();
        String leaked = single.submit(() -> TRACE.get().toString()).get();
        System.out.println("leaked=" + leaked);              // 上一个任务的值还在这儿
        single.submit(() -> TRACE.remove()).get();
        String cleaned = single.submit(() -> TRACE.get().toString()).get();
        System.out.println("afterRemove=[" + cleaned + "]");

        single.shutdown();
        io.shutdown();
    }

    static int quote(String sku) {
        try {
            Thread.sleep(50);   // 模拟阻塞 IO，正是不能放进 commonPool 的原因
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return PRICE.get(sku);
    }
}

