// IocProxyLab.java —— Java 17，只用 JDK 自带 API，单文件可编译
//
// 编译并运行：
//   javac -d out IocProxyLab.java
//   java -cp out IocProxyLab
//
// 预期输出：
//   [proxy] enter transfer
//   [audit] transfer:alice->bob
//   alice=7500, bob=2500
//   [audit] transfer:bob->alice
//   alice=8000, bob=2000
//
// 观察点：第二次是直接调目标对象（等价于 this 自调用），
// 只有 [audit] 没有 [proxy]，注解/切面在自调用下全部失效。

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;

public class IocProxyLab {

    // 接口：JDK 动态代理只能代理接口
    interface TransferService {
        void transfer(String from, String to, int cents);

        void audit(String action);
    }

    // 目标对象：业务逻辑都在这里，它不知道自己会被代理
    static class TransferServiceImpl implements TransferService {
        private final Map<String, Integer> balances = new HashMap<>();

        TransferServiceImpl() {
            balances.put("alice", 10_000);
            balances.put("bob", 0);
        }

        @Override
        public void transfer(String from, String to, int cents) {
            // 自调用：this 是目标对象，不是代理，audit 上的切面不会执行
            this.audit("transfer:" + from + "->" + to);
            balances.put(from, balances.get(from) - cents);
            balances.put(to, balances.get(to) + cents);
        }

        @Override
        public void audit(String action) {
            System.out.println("[audit] " + action);
        }

        int balanceOf(String user) {
            return balances.get(user);
        }
    }

    // 极简 IoC 容器：负责实例化、包代理、按类型取用
    static class MiniContext {
        private final Map<Class<?>, Object> beans = new HashMap<>();

        <T> void register(Class<T> type, T target, boolean needProxy) {
            // 代理只包在容器这一层，调用方拿到的就是代理
            beans.put(type, needProxy ? withLogging(type, target) : target);
        }

        @SuppressWarnings("unchecked")
        <T> T get(Class<T> type) {
            Object bean = beans.get(type);
            if (bean == null) {
                throw new IllegalStateException("no bean: " + type.getName());
            }
            return (T) bean;
        }
    }

    // 切面替身：进方法前打一行，等价于事务/日志拦截器
    @SuppressWarnings("unchecked")
    static <T> T withLogging(Class<T> type, T target) {
        InvocationHandler handler = (proxy, method, args) -> {
            System.out.println("[proxy] enter " + method.getName());
            try {
                // 必须显式转发，否则业务逻辑不会执行
                return method.invoke(target, args);
            } catch (InvocationTargetException e) {
                // 拆掉反射包装，让上层看到原始业务异常
                throw e.getCause();
            }
        };
        // 第三个参数必须是接口数组；传类会抛 IllegalArgumentException
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] { type }, handler);
    }

    public static void main(String[] args) {
        MiniContext ctx = new MiniContext();
        TransferServiceImpl raw = new TransferServiceImpl();
        ctx.register(TransferService.class, raw, true);

        // ① 通过容器取到代理，调用穿过代理
        TransferService proxied = ctx.get(TransferService.class);
        proxied.transfer("alice", "bob", 2_500);
        System.out.println("alice=" + raw.balanceOf("alice") + ", bob=" + raw.balanceOf("bob"));

        // ② 直接调目标对象：等价于 this 自调用，代理被绕过
        raw.transfer("bob", "alice", 500);
        System.out.println("alice=" + raw.balanceOf("alice") + ", bob=" + raw.balanceOf("bob"));
    }
}

